import ghidra.app.decompiler.*; import ghidra.app.script.GhidraScript; import ghidra.program.model.listing.*;
public class NarrowphaseDefs extends GhidraScript { public void run()throws Exception{DecompInterface d=new DecompInterface();d.openProgram(currentProgram);long[] xs={0x00425c70L,0x004264c0L,0x00426170L};for(long x:xs){Function f=getFunctionContaining(toAddr(x));println("\n=== "+toAddr(x)+" "+(f==null?"<missing>":f.getName())+" ===");if(f!=null){DecompileResults r=d.decompileFunction(f,240,monitor);if(r.getDecompiledFunction()!=null)println(r.getDecompiledFunction().getC());}}d.dispose();}}
